tools.usage:
ResetParameters;
AddStringParameter('<name>', '<value>');
RunProcess('<Server>:<Command>');

tools.example:
// Refresh the PCB workspace
ResetParameters;
AddStringParameter('Action', 'Redraw');
RunProcess('PCB:Zoom');

// Refresh the schematic workspace
ResetParameters;
AddStringParameter('Action', 'All');
RunProcess('Sch:Zoom');

Var Doc : IServerDocument;
Begin
  Doc := Client.OpenDocument('PCB', 'D:\work\board.PcbDoc');
  If Doc <> Nil Then Client.ShowDocument(Doc);
End;

PCBServer.PreProcess;
Track := PCBServer.PCBObjectFactory(eTrackObject, eNoDimension, eCreate_Default);
Track.Layer := eTopLayer;
Track.Width := MilsToCoord(10);
Board.AddPCBObject(Track);
PCBServer.SendMessageToRobots(Board.I_ObjectAddress, c_Broadcast, PCBM_BoardRegisteration, Track.I_ObjectAddress);
PCBServer.PostProcess;

Board := PCBServer.GetCurrentPCBBoard;
If Board = Nil Then Exit;
ShowMessage(Board.FileName + ' has ' + IntToStr(Board.BoardOutline.PointCount) + ' outline vertices');

Via := PCBServer.PCBObjectFactory(eViaObject, eNoDimension, eCreate_Default);
Via.X := MilsToCoord(7500);
Via.Y := MilsToCoord(7500);
Via.Size := MilsToCoord(50);
Via.HoleSize := MilsToCoord(20);
Via.LowLayer := eTopLayer;
Via.HighLayer := eBottomLayer;
Board.AddPCBObject(Via);

tools.usage:
Iter := Board.BoardIterator_Create;
Iter.AddFilter_ObjectSet(MkSet(eViaObject));
Iter.AddFilter_LayerSet(AllLayers);
Iter.AddFilter_Method(eProcessAll);
Obj := Iter.FirstPCBObject; … Board.BoardIterator_Destroy(Iter);

tools.example:
Iter := Board.BoardIterator_Create;
Iter.AddFilter_ObjectSet(MkSet(eViaObject));
Iter.AddFilter_LayerSet(AllLayers);
Iter.AddFilter_Method(eProcessAll);
Via := Iter.FirstPCBObject;
While Via <> Nil Do Begin
  Count := Count + 1;
  Via := Iter.NextPCBObject;
End;
Board.BoardIterator_Destroy(Iter);

// widen every track on a net
While Track <> Nil Do Begin
  If (Track.Net <> Nil) And (Track.Net.Name = 'VBUS') Then Begin
    PCBServer.SendMessageToRobots(Track.I_ObjectAddress, c_Broadcast, PCBM_BeginModify, c_NoEventData);
    Track.Width := MMsToCoord(0.8);
    PCBServer.SendMessageToRobots(Track.I_ObjectAddress, c_Broadcast, PCBM_EndModify, c_NoEventData);
  End;
  Track := Iter.NextPCBObject;
End;

GIter := Comp.GroupIterator_Create;
GIter.AddFilter_ObjectSet(MkSet(ePadObject));
Pad := GIter.FirstPCBObject;
While Pad <> Nil Do Begin
  PadCount := PadCount + 1;
  Pad := GIter.NextPCBObject;
End;
Comp.GroupIterator_Destroy(GIter);

Doc := SchServer.GetCurrentSchDocument;
If Doc = Nil Then Exit;
SchServer.ProcessControl.PreProcess(Doc, '');
// … edits …
SchServer.ProcessControl.PostProcess(Doc, '');
Doc.GraphicallyInvalidate;

Port := SchServer.SchObjectFactory(ePort, eCreate_Default);
Port.Name := 'VOUT';
Port.Location := Point(MilsToCoord(500), MilsToCoord(500));
Doc.RegisterSchObjectInContainer(Port);
Doc.GraphicallyInvalidate;

Iter := Doc.SchIterator_Create;
Iter.AddFilter_ObjectSet(MkSet(eSchComponent));
Cmp := Iter.FirstSchObject;
While Cmp <> Nil Do Begin
  Report.Add(Cmp.Designator.Text + ' = ' + Cmp.Comment.Text);
  Cmp := Iter.NextSchObject;
End;
Doc.SchIterator_Destroy(Iter);

PIter := Cmp.SchIterator_Create;
PIter.AddFilter_ObjectSet(MkSet(eParameter));
Param := PIter.FirstSchObject;
While Param <> Nil Do Begin
  If Param.Name = 'MPN' Then ShowMessage(Param.Value);
  Param := PIter.NextSchObject;
End;
Cmp.SchIterator_Destroy(PIter);

Wire := SchServer.SchObjectFactory(eWire, eCreate_Default);
Wire.Location := Point(MilsToCoord(100), MilsToCoord(100));
Wire.SetState_VerticesCount(2);
Wire.Vertex[1] := Point(MilsToCoord(100), MilsToCoord(100));
Wire.Vertex[2] := Point(MilsToCoord(300), MilsToCoord(100));
Doc.RegisterSchObjectInContainer(Wire);

WS := GetWorkspace;
Prj := WS.DM_FocusedProject;
Prj.DM_Compile;
For i := 0 To Prj.DM_PhysicalDocumentCount - 1 Do
  Report.Add(Prj.DM_PhysicalDocuments(i).DM_FullPath);

// deselect everything on the PCB
ResetParameters;
AddStringParameter('Scope', 'All');
RunProcess('PCB:DeSelect');

Var
  i : Integer;
  s : String;
Begin
  For i := 0 To 9 Do s := s + IntToStr(i);
  ShowMessage(s);
End;
